/**
 * Whether `actor` may see `project` at all. A `private` project is visible
 * only to an admin/owner, platform staff, its lead, or an explicit project
 * member; `org` and `public` projects are visible to the whole tenant.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(actor.orgId, project.id, actor.userId);
}

/**
 * Private projects in the org that `actor` cannot see, for filtering listings
 * so a hidden project's rows never leak into a page or its `total`.
 */
export async function listHiddenProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin")) {
    return [];
  }

  const privateProjects = await projectRepo.listPrivateProjectLeads(orgId);
  if (privateProjects.length === 0) return [];

  const memberProjectIds = new Set(
    await projectMemberRepo.listMemberProjectIds(orgId, actor.userId),
  );

  return privateProjects
    .filter(
      (project) =>
        project.leadId !== actor.userId && !memberProjectIds.has(project.id),
    )
    .map((project) => project.id);
}

