import { afterAll, beforeAll, describe, expect, it } from "vitest";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError } from "@/server/services/_support";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, useTemporaryDatabase, type Tenant } from "./server/_support/fixtures";

describe("private project visibility (sanity)", () => {
  let cleanup: () => void;
  let tenant: Tenant;

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    tenant = await createTenant("visitest");
  });

  afterAll(() => cleanup());

  it("hides a private project from a non-member viewer/member but shows it to admin/owner/lead/member-of", async () => {
    const privateProject = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Secret",
      slug: "secret",
      key: "SEC",
      description: null,
      visibility: "private",
      leadId: tenant.userIds.member,
      color: "#000000",
      targetDate: null,
    });

    // viewer: not admin/owner, not lead, not member -> hidden
    await expect(
      projectService.getProject(tenant.actors.viewer, tenant.org.id, "secret"),
    ).rejects.toThrow(NotFoundError);

    // member (non-lead, non-member-of-project) -> hidden
    const otherMemberActor = tenant.actors.viewer; // reuse viewer as "random member" stand-in
    expect(
      await projectService.canViewProject(otherMemberActor, privateProject),
    ).toBe(false);

    // admin -> visible
    expect(await projectService.canViewProject(tenant.actors.admin, privateProject)).toBe(
      true,
    );
    // owner -> visible
    expect(await projectService.canViewProject(tenant.actors.owner, privateProject)).toBe(
      true,
    );
    // lead -> visible
    expect(
      await projectService.canViewProject(tenant.actors.member, privateProject),
    ).toBe(true);

    const project = await projectService.getProject(
      tenant.actors.admin,
      tenant.org.id,
      "secret",
    );
    expect(project.project.id).toBe(privateProject.id);

    // Explicit project membership grants visibility to an otherwise-excluded actor.
    await projectMemberRepo.addProjectMember(
      tenant.org.id,
      privateProject.id,
      tenant.userIds.viewer,
    );
    expect(
      await projectService.canViewProject(tenant.actors.viewer, privateProject),
    ).toBe(true);

    // listProjects excludes it for a non-member, includes it for admin, and `total` matches.
    const viewerListStillHidden = await projectService.listProjects(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 50,
    });
    // owner sees both (org project + private project)
    expect(viewerListStillHidden.items.some((p) => p.project.id === privateProject.id)).toBe(
      true,
    );

    const randomNonMember = tenant.actors.member; // lead is member role in this fixture; use its own visibility (it's the lead)
    // Create a brand-new project that this actor has no relation to, to test true exclusion.
    const otherPrivate = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other Secret",
      slug: "other-secret",
      key: "OSEC",
      description: null,
      visibility: "private",
      leadId: tenant.userIds.owner,
      color: "#111111",
      targetDate: null,
    });

    const listForRandom = await projectService.listProjects(randomNonMember, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(listForRandom.items.some((p) => p.project.id === otherPrivate.id)).toBe(false);

    const listForOwner = await projectService.listProjects(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(listForOwner.items.some((p) => p.project.id === otherPrivate.id)).toBe(true);
    expect(listForOwner.total).toBeGreaterThanOrEqual(listForRandom.total);

    // Writes on a hidden project throw NotFoundError, not PermissionDeniedError.
    await expect(
      projectService.updateProject(randomNonMember, {
        orgId: tenant.org.id,
        projectId: otherPrivate.id,
        name: "Renamed",
      }),
    ).rejects.toThrow(NotFoundError);

    // Issue under the hidden project is hidden too.
    const issue = await issueRepo.insertIssue(
      {
        orgId: tenant.org.id,
        projectId: otherPrivate.id,
        title: "Hidden issue",
        description: null,
        status: "backlog",
        priority: "none",
        assigneeId: null,
        parentId: null,
        estimate: null,
        dueAt: null,
        labelIds: [],
      },
      tenant.userIds.owner,
      1,
    );

    await expect(
      issueService.getIssue(randomNonMember, tenant.org.id, issue.id),
    ).rejects.toThrow(NotFoundError);
    await expect(
      issueService.getIssue(tenant.actors.owner, tenant.org.id, issue.id),
    ).resolves.toBeTruthy();

    // Org-wide issue list excludes the hidden issue and total reflects that.
    const orgWideForRandom = await issueService.listIssues(randomNonMember, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(orgWideForRandom.items.some((i) => i.id === issue.id)).toBe(false);

    const orgWideForOwner = await issueService.listIssues(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 50,
    });
    expect(orgWideForOwner.items.some((i) => i.id === issue.id)).toBe(true);

    // Comment thread on the hidden issue is hidden too.
    await expect(
      commentService.getThread(randomNonMember, tenant.org.id, issue.id),
    ).rejects.toThrow(NotFoundError);
    await expect(
      commentService.getThread(tenant.actors.owner, tenant.org.id, issue.id),
    ).resolves.toBeTruthy();
  });
});

